package com.campusnova.model; import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String email; private String name; private String role="STUDENT"; private LocalDateTime createdAt=LocalDateTime.now(); public User(){} public Long getId(){return id;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getRole(){return role;} public void setRole(String v){role=v;} }
